// examples/synthetic-pulse-kinetics.json: the synthetic pin pulsed by a $3 reactivity insertion, with the power history GENERATED by point
// kinetics (six delayed groups, prompt generation time 40 us, prompt fuel-temperature coefficient -1e-4 dk/k/K) instead of written as a table.
// Synthetic: the neutronics constants are textbook values (Keepin's U-235 data) and a TRIGA-like generation time, not any reactor's.
// Run: node scripts/make-kinetics-pulse.cjs
const fs = require("fs");
const path = require("path");
const root = path.join(__dirname, "..");
const d = JSON.parse(fs.readFileSync(path.join(root, "examples", "synthetic-pulse.json"), "utf8"));
const q = (value, unit) => ({ value, unit });
const KEEPIN = [
  [0.000215, 0.0124],
  [0.001424, 0.0305],
  [0.001274, 0.111],
  [0.002568, 0.301],
  [0.000748, 1.14],
  [0.000273, 3.01],
];
d.caseId = "synthetic-pulse-kinetics";
d.name = "Synthetic pulse from point kinetics: a $3 insertion on the synthetic pin (illustrative numbers, not a real reactor)";
d.description =
  "The power history is not a table: it is generated by six-group point kinetics from a $3 reactivity insertion (a step), a 40 us prompt generation time and a prompt fuel-temperature coefficient of -1e-4 dk/k/K, " +
  "for 100 pins of 0.5 m with the modelled slice at the average power, starting from 1 kW of reactor power. The feedback temperature is the fuel's own average if the heat stayed where it was made, " +
  "using the fuel's heat capacity (3 MJ/m3/K); the results check it against the pin's real average. The delayed-neutron data are Keepin's U-235 set; the other numbers are chosen, not any reactor's. " +
  "Thermal only for the pin; no control action, coolant or void feedback.";
delete d.transient.powerHistory;
d.transient.pointKinetics = {
  reactivityInsertion: q(3, "$"),
  insertionTime: q(0, "ms"),
  promptGenerationTime: q(40, "us"),
  delayedGroups: KEEPIN.map(([beta, lambda]) => ({ fraction: q(beta, "1"), decayConstant: q(lambda, "1/s") })),
  delayedSource: "Keepin (1957) thermal-fission U-235 six-group set, sum 0.006502; textbook data, not measured for any reactor",
  feedback: { model: "constant", coefficient: q(-1e-4, "dk/k/K"), source: "synthetic: chosen to give a TRIGA-like pulse (about 10 ms wide, a few hundred kelvin); not any reactor's coefficient" },
  initialPower: q(1, "kW"),
  core: { pins: 100, activeLength: q(0.5, "m"), peakingFactor: q(1, "1") },
};
d.transient.endTime = q(60, "ms");
d.transient.timeStep = q(0.05, "ms");
d.transient.outputs = 12;
fs.writeFileSync(path.join(root, "examples", "synthetic-pulse-kinetics.json"), JSON.stringify(d, null, 2) + "\n");
console.log("wrote examples/synthetic-pulse-kinetics.json");
